describe('Table Data Review - #table1', () => {
  beforeEach(() => {
    cy.visit('/tables');
  });

  it('should verify table #table1 has correct header and rows', () => {
    // Verify table header exists
    cy.get('[id="table1"]').should('be.visible');
    cy.get('[id="table1"]').should('contain', 'Last Name');
    cy.get('[id="table1"]').should('contain', 'First Name');
    cy.get('[id="table1"]').should('contain', 'Email');
    cy.get('[id="table1"]').should('contain', 'Due');

    // Verify table body contains 4 rows
    cy.get('[id="table1"]').then((table) => {
      const rows = table.find('tr');
      cy.wrap(rows).should('have.length', 5);
      cy.wrap(rows).first().should('contain', 'Last Name');
      cy.wrap(rows).last().should('contain', 'Due');
    });

    // Verify specific row contains email 'jsmith@gmail.com'
    cy.get('[id="table1"]').then((table) => {
      cy.wrap(table.find('tr')).first().then((firstRow) => {
        cy.wrap(firstRow).should('contain', 'Smith');
        cy.wrap(firstRow).first('td').then((cell) => {
          cy.wrap(cell).should('contain', 'jsmith@gmail.com');
        });
      });
    });
  });

  it('should handle empty table rows gracefully', () => {
    // Intercept the API call to get table data
    cy.intercept('GET', '/api/tables/table1').as('getTableData');
    cy.wait('@getTableData');

    // Verify table is empty
    cy.get('[id="table1"]').should('be.visible');
    cy.get('[id="table1"]').then((table) => {
      cy.wrap(table).should('have.length', 1);
      cy.wrap(table).first().should('contain', 'No data available');
    });

    // Verify empty row is displayed
    cy.get('[id="table1"]').then((table) => {
      cy.wrap(table.find('tr')).first().should('contain', 'No data available');
    });
  });
});
